WITH alvo AS (SELECT * FROM UNNEST(['PA-1506187-94551B72659E427F961D2F62CEBA7392','MS-5006606-4693892971CF47B4B2684C3A94950BEE','PA-1506161-EE5157E8CA8B4DF280FC7F9D371FF17A','BA-2921401-9177991E4861442EACFE3ACDDC06DB91','BA-2928109-0F43ABB998F5484394BAA55A4964A2BD','BA-2929057-3DE9EF4059BE416EBC88EAAE603F1B5F','BA-2929057-C5D11EE026A64399A6EF36764E8739E9','BA-2913705-C31099AB04E24F15B9941AAAF17DC244','BA-2929057-2483416C90F94058B15FED07A5FE9FB7','RS-4322301-411110B140A543DB906D80C3081D1822','BA-2930766-9CCE04D4FED440E0844D0C38B9C89B70','PA-1506187-CEAD1A3AC3E14F5DB2FC0B93E54E7E98','BA-2901601-2D6EA3618F4A48BF87E2EB78992B2968','RS-4322301-249321677C5045DC84BE25A36C504F31','RS-4322301-8DD943476D08400A931895B8A17A8BA9','BA-2916500-9222A7C0C77E4E019B498875C6578189','BA-2929057-60EC867CE3FF4AEAA712CD4AE3992CCB','BA-2902005-876B8A8CE62D40119A8446C4262A5AC7','RS-4322301-0BBDEB7272784E4DACA585E486AE37A9','BA-2926509-E3BCDCD3078C4BADBC80D0166EACCAF6']) AS id_imovel),latest AS (SELECT a.id_imovel,a.id_municipio,a.sigla_uf,a.geometria FROM `basedosdados.br_sfb_sicar.area_imovel` a WHERE a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY a.id_imovel ORDER BY a.data_extracao DESC)=1),pairs AS (SELECT x.id_imovel alvo_id,y.id_imovel sobreposto_id FROM latest x JOIN alvo USING(id_imovel) JOIN latest y ON y.id_municipio=x.id_municipio AND y.id_imovel!=x.id_imovel WHERE ST_INTERSECTS(x.geometria,y.geometria)) SELECT alvo_id,COUNT(*) outros_imoveis_sobrepostos,ARRAY_AGG(sobreposto_id ORDER BY sobreposto_id LIMIT 10) exemplos_ids FROM pairs GROUP BY alvo_id ORDER BY alvo_id